$$\begin{array}{l}
  {{\int_{1}^{2}{\frac{1}{x}\mathit{dx}}} \approx {\Delta x\lbrack f(1.1) + f(1.3) + f(1.5) + f(1.7) + f(1.9)\rbrack}} \\
  {\phantom{\int_{1}^{2}{\frac{1}{x}\mathit{du}}} = {\frac{1}{5}\left( {\frac{1}{1.1} + \frac{1}{1.3} + \frac{1}{1.5} + \frac{1}{1.7} + \frac{1}{1.9}} \right)}} \\
